import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.DnrXFDHb.js";const k=JSON.parse('{"title":"安装","description":"StreamMUSE 环境搭建与依赖安装指南","frontmatter":{"title":"安装","description":"StreamMUSE 环境搭建与依赖安装指南"},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md","lastUpdated":1775420276000}'),l={name:"getting-started/installation.md"};function n(h,a,o,p,r,d){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>Python 3.10 或更高版本</li><li><a href="https://github.com/astral-sh/uv" target="_blank" rel="noreferrer">uv</a> 包管理器（推荐）</li><li>Git</li></ul><h2 id="步骤一-克隆仓库" tabindex="-1">步骤一：克隆仓库 <a class="header-anchor" href="#步骤一-克隆仓库" aria-label="Permalink to &quot;步骤一：克隆仓库&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">repository-ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> StreamMUSE-new-sys</span></span></code></pre></div><h2 id="步骤二-安装主包依赖" tabindex="-1">步骤二：安装主包依赖 <a class="header-anchor" href="#步骤二-安装主包依赖" aria-label="Permalink to &quot;步骤二：安装主包依赖&quot;">​</a></h2><p>使用 <code>uv sync</code> 安装 <code>pyproject.toml</code> 中声明的所有依赖并创建虚拟环境：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span></code></pre></div><h2 id="步骤三-安装改版-transformers" tabindex="-1">步骤三：安装改版 Transformers <a class="header-anchor" href="#步骤三-安装改版-transformers" aria-label="Permalink to &quot;步骤三：安装改版 Transformers&quot;">​</a></h2><p>StreamMUSE 使用了经过修改的 HuggingFace Transformers，以支持 RoFormer 的位置编码。需要单独以 editable 模式安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> transformers</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span></code></pre></div><h2 id="步骤四-验证安装" tabindex="-1">步骤四：验证安装 <a class="header-anchor" href="#步骤四-验证安装" aria-label="Permalink to &quot;步骤四：验证安装&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streammuse-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>若安装成功，将看到完整的参数帮助信息，以 <code>usage: streammuse-cli</code> 开头。</p><hr><h2 id="可选依赖" tabindex="-1">可选依赖 <a class="header-anchor" href="#可选依赖" aria-label="Permalink to &quot;可选依赖&quot;">​</a></h2><h3 id="实时音频输出-output-type-audio" tabindex="-1">实时音频输出（<code>--output-type audio</code>） <a class="header-anchor" href="#实时音频输出-output-type-audio" aria-label="Permalink to &quot;实时音频输出（`--output-type audio`）&quot;">​</a></h3><p>实时音频播放依赖 <code>python-rtmidi</code> 提供的虚拟 MIDI 端口，以及系统 MIDI 合成器（如 macOS 自带的 FluidSynth 或 DLSMusicDevice）。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS 通常无需额外安装；Linux 可能需要：</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fluidsynth</span></span></code></pre></div><h3 id="gpu-推理-stanley-本地模式-inference-type-stanley" tabindex="-1">GPU 推理（Stanley 本地模式，<code>--inference-type stanley</code>） <a class="header-anchor" href="#gpu-推理-stanley-本地模式-inference-type-stanley" aria-label="Permalink to &quot;GPU 推理（Stanley 本地模式，`--inference-type stanley`）&quot;">​</a></h3><p>本地模式需要 CUDA 12.8+ 及对应版本的 PyTorch。若仅使用 HTTP 模式（对接推理服务器），则不需要 GPU。</p><h3 id="macos-apple-silicon-lekai-本地推理" tabindex="-1">macOS Apple Silicon（Lekai 本地推理） <a class="header-anchor" href="#macos-apple-silicon-lekai-本地推理" aria-label="Permalink to &quot;macOS Apple Silicon（Lekai 本地推理）&quot;">​</a></h3><p>在 M1/M2/M3 上运行 Lekai 本地服务时，建议：</p><ol><li>使用项目虚拟环境中的 PyTorch（<code>uv sync</code> 后自动安装）。</li><li>启动前确认 MPS 可用：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import torch; print(torch.backends.mps.is_built(), torch.backends.mps.is_available())&quot;</span></span></code></pre></div><ol start="3"><li>如果遇到 MPS 不支持的算子，可设置 <code>LEKAI_ENABLE_MPS_FALLBACK=true</code>，让服务自动回退到 CPU。</li><li>首次验证建议用较短生成长度（如 <code>generation-length-frames=8~16</code>），降低内存压力。</li></ol><p>常见问题：</p><ol><li><code>ModuleNotFoundError</code>：请确保从仓库根目录执行命令，或使用 <code>uv run ...</code>。</li><li><code>state_dict</code> key mismatch：确认 checkpoint 与当前模型结构匹配，优先使用 <code>.safetensors</code>。</li><li>推理延迟过高：先降低 <code>generation-length-frames</code>，再提高 <code>generation-interval-ticks</code>。</li></ol><hr><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./quickstart.html">快速上手</a>：启动 fake 服务器，运行第一个示例</li><li><a href="./configuration.html">配置项</a>：了解所有可用的参数</li></ul>',31)])])}const u=s(l,[["render",n]]);export{k as __pageData,u as default};
